const mails = await api.get("/mails", { label: "refund" });
const items = mails.items || [];
const ids = [...new Set(items.map(m => m.customer_id).filter(Boolean))];
const customers = [];
for (const id of ids) {
  const c = await api.get(`/customers/${id}`);
  customers.push({ id: c.id, name: c.name, tier: c.tier });
}
return { refundMailCount: items.length, customerCount: ids.length, gold: customers.filter(c => c.tier === "gold"), all: customers };

